cd /work/store/kafka && python3 - <<'PY'
import re,collections

def analyze(path, cap=None):
    sent=collections.defaultdict(dict)
    polled=collections.defaultdict(set)
    ops=0; sends=0; polls=0; pairs=0; keys=set(); series=0; maxun=0
    for line in open(path):
        m=re.search(r':type (:ok|:info|:fail|:invoke), :process (\d+), :f :(\w+)', line)
        if not m: continue
        typ=m.group(1); f=m.group(3)
        ops+=1
        if typ==':ok':
            if f=='send':
                mm=re.search(r'\[\[:send "([^"]*)" \[(\d+) (.*?)\]\]\]$', line.strip())
                if mm:
                    k=mm.group(1); off=int(mm.group(2)); val=mm.group(3)
                    sent[k][off]=val; keys.add(k); sends+=1
            elif f=='poll':
                polls+=1
                i=line.find('[[:poll {')
                body=line[i+8:]
                for km in re.finditer(r'"([^"]*)" \[(.*?)\](?=, "| \}|\}\])', body):
                    k=km.group(1); arr=km.group(2)
                    vals=re.findall(r'\[(\d+) (.*?)\]', arr)
                    for off,val in vals[:cap] if cap else vals:
                        polled[k].add(val); pairs+=1
        n=0
        for k in sent:
            if set(sent[k].values()) - polled[k]: n+=1
        series+=n; maxun=max(maxun,n)
    return dict(ops=ops,sends=sends,polls=polls,pairs=pairs,keys=len(keys),
                series=series, avg_unseen=round(series/max(ops,1),1), max_unseen=maxun)

for d in ['20261122T235035.029Z','20261122T235526.041Z']:
    print(d, analyze(d+'/history.edn'))
